function spParse(record){
  record=String(record||'').trim();
  var parts=record.split(/\s+/).filter(Boolean);
  var mechs=[];
  if(parts[0] && /^v=spf1$/i.test(parts[0])){
    for(var i=1;i<parts.length;i++){
      var tok=parts[i], q='+', body=tok;
      if('+-?~'.indexOf(tok[0])>=0){ q=tok[0]; body=tok.slice(1); }
      var mm=body.match(/^([a-z0-9]+)(:(.*))?$/i);
      mechs.push({ raw:tok, qualifier:q, mechanism: mm?mm[1].toLowerCase():body, value: (mm&&mm[3]!==undefined)?mm[3]:'' });
    }
    return { version:'spf1', mechanisms:mechs, ok:true };
  }
  return { version:'', mechanisms:[], ok:false };
}
function spExplainQual(q){
  return {'+':'放行','-':'硬失败（拒绝）','~':'软失败（标记）','?':'中立（放行但不保证）'}[q]||q;
}
function spDnsLookups(mechs){
  var n=0;
  for(var i=0;i<mechs.length;i++){ var m=mechs[i].mechanism; if(m==='include'||m==='a'||m==='mx'||m==='exists'||m==='redirect'||m==='ptr') n++; }
  return n;
}
function spScore(mechs){
  var lookups=spDnsLookups(mechs), last=null;
  for(var i=0;i<mechs.length;i++) if(mechs[i].mechanism==='all') last=mechs[i];
  var checks=[];
  function add(name,pass,weight){ checks.push({name:name,pass:!!pass,weight:weight}); }
  add('含 v=spf1 版本', true, 10);
  add('以 all 收尾', !!last, 20);
  add('硬失败 -all', last && last.qualifier==='-', 25);
  add('无 +all 开放放行', !(last && last.qualifier==='+'), 20);
  add('DNS 查询 ≤ 10', lookups<=10, 15);
  add('无 ptr 机制', mechs.every(function(m){return m.mechanism!=='ptr';}), 10);
  var got=0,total=0;
  for(var j=0;j<checks.length;j++){ total+=checks[j].weight; if(checks[j].pass) got+=checks[j].weight; }
  var grade='F';
  if(got>=90)grade='A'; else if(got>=75)grade='B'; else if(got>=60)grade='C'; else if(got>=40)grade='D';
  return { score:got, max:total, grade:grade, lookups:lookups, checks:checks };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { spParse:spParse, spExplainQual:spExplainQual, spDnsLookups:spDnsLookups, spScore:spScore };
}
if (typeof window !== 'undefined') {
  window.SpfForgePure = { spParse:spParse, spExplainQual:spExplainQual, spDnsLookups:spDnsLookups, spScore:spScore };
}
